import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: (project_basename, framework, package_id) -> (requested, resolved)
def build_lookup(data):
    lookup = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                lookup[(name, fw['framework'], pkg['id'])] = (pkg['requestedVersion'], pkg['resolvedVersion'])
    return lookup

b = build_lookup(baseline)
a = build_lookup(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))

changes = []
unchanged = []
for key in all_keys:
    proj, fw, pkg = key
    if key in b and key in a:
        if b[key][1] != a[key][1]:
            changes.append((proj, fw, pkg, b[key][1], a[key][1], 'Aligned to highest version'))
        else:
            unchanged.append((proj, fw, pkg, a[key][1]))
    elif key in a and key not in b:
        changes.append((proj, fw, pkg, '-', a[key][1], 'Added'))
    elif key in b and key not in a:
        changes.append((proj, fw, pkg, b[key][1], '-', 'Removed'))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'  {c[0]} ({c[1]}) | {c[2]} | {c[3]} -> {c[4]} | {c[5]}')
else:
    print('  None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'  {u[0]} ({u[1]}) | {u[2]} | {u[3]}')
"

